/**
 * Shape parameters in SI, tagged by `type` (same spelling as
 * [`super::ComponentType`]). Hollow parts carry `id`; solid parts have `id = 0`.
 */
export type EvalShape =
  | {
      type: "nose_cone";
      shape: NoseShape;
      shape_param: number;
      length: number;
      od: number;
      /**
       * 0 = solid.
       */
      thickness: number;
      shoulder?: EvalShoulder | null;
    }
  | {
      type: "body_tube";
      length: number;
      od: number;
      id: number;
    }
  | {
      type: "transition";
      shape: NoseShape;
      shape_param: number;
      length: number;
      fore_od: number;
      aft_od: number;
      thickness: number;
      fore_shoulder?: EvalShoulder | null;
      aft_shoulder?: EvalShoulder | null;
    }
  | {
      type: "trapezoidal_fin_set";
      count: number;
      thickness: number;
      cross_section: FinCrossSection;
      cant: number;
      fillet_radius: number;
      tab?: EvalFinTab | null;
      root_chord: number;
      tip_chord: number;
      span: number;
      sweep: number;
    }
  | {
      type: "elliptical_fin_set";
      count: number;
      thickness: number;
      cross_section: FinCrossSection;
      cant: number;
      fillet_radius: number;
      tab?: EvalFinTab | null;
      root_chord: number;
      span: number;
    }
  | {
      type: "freeform_fin_set";
      count: number;
      thickness: number;
      cross_section: FinCrossSection;
      cant: number;
      fillet_radius: number;
      tab?: EvalFinTab | null;
      /**
       * Planform `[x, y]` from the root LE.
       */
      points: [number, number][];
    }
  | {
      type: "tube_fin_set";
      count: number;
      length: number;
      od: number;
      id: number;
    }
  | {
      type: "inner_tube";
      length: number;
      od: number;
      id: number;
      motor_mount: boolean;
      overhang: number;
    }
  | {
      type: "coupler";
      length: number;
      od: number;
      id: number;
    }
  | {
      type: "centering_ring";
      length: number;
      od: number;
      id: number;
    }
  | {
      type: "bulkhead";
      length: number;
      od: number;
    }
  | {
      type: "engine_block";
      length: number;
      od: number;
      id: number;
    }
  | {
      type: "launch_lug";
      length: number;
      od: number;
      id: number;
    }
  | {
      type: "rail_button";
      /**
       * Outer (base and flange) diameter.
       */
      od: number;
      /**
       * Neck (waist) diameter.
       */
      id: number;
      /**
       * Total height above the body surface.
       */
      height: number;
      /**
       * Base height at the body surface (source default `height / 4`;
       * 0 when absent from older evaluated JSON).
       */
      base_height?: number;
      /**
       * Flange height at the outer face (source default `height / 4`;
       * 0 when absent from older evaluated JSON).
       */
      flange_height?: number;
    }
  | {
      type: "parachute";
      diameter: number;
      cd: number;
      spill_hole: number;
      /**
       * Shroud lines (0 = none given).
       */
      line_count?: number;
      line_length?: number;
      /**
       * Shroud-line material name (resolved in `materials`).
       */
      line_material?: string | null;
      packed_length: number;
      packed_diameter: number;
    }
  | {
      type: "streamer";
      length: number;
      width: number;
      cd: number;
      packed_length: number;
      packed_diameter: number;
    }
  | {
      type: "shock_cord";
      cord_length: number;
      packed_length: number;
      packed_diameter: number;
    }
  | {
      type: "mass_component";
      mass: number;
      length: number;
      od: number;
      role?: MassRole | null;
    }
  | {
      type: "tank";
      length: number;
      od: number;
      wall: number;
      end_cap: EndCap;
      volume: number;
      propellant?: string | null;
      propellant_mass: number;
    };

